registerRefData('nsw-cond-n-1491',{"id":1491,"pan":null,"ref":"2020/054","address":"334 Pownall Road Mullaley 2379,259 Barker Road Marys Mount 2380","description":"Proposed Landfill Operation, Marys Mount Quarry","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2021-06-24","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSNTH-55!20210702T061900.476 GMT","sha256":"995e258db0a1d34bcc2074a9a7a9deaf296471e8ff093696d88a30bc7b7fc070","pages":18,"layout":"numbered","n":11,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/1491.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/proposed-landfill-operation-marys-mount-quarry","lga":"GUNNEDAH","conditions":[{"label":"1","code":null,"number":"1","title":"PANEL REF - LGA - DA NO. PPSNTH-55 - Gunnedah - 2020/054","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Establishment of a Waste Disposal Facility within the void of an existing\napproved and operating Extractive Industry (Quarry) for disposal of a\nmaximum 200,000 tonnes of waste (non-putrescible waste)","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"","text":"STREET ADDRESS 334 Pownall Rd, Mullaley and ‘Beulah’ 259 Barker Rd, Marys Mount","stage":"general","stage_basis":"heading","page":3},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Outline Planning Consultants Pty Ltd on behalf of Gunnedah Quarry","text":"Products","stage":"general","stage_basis":"heading","page":3},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Designated development - waste management facility or works","stage":"general","stage_basis":"heading","page":3},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n Environmental planning instruments:\no State Environmental Planning Policy (State and Regional\nDevelopment) 2011\no State Environmental Planning Policy No 33 - Hazardous and\nOffensive Development\no State Environmental Planning Policy No 55 - Remediation of Land\no State Environmental Planning Policy (Mining, Petroleum\nProduction and Extractive Industry) 2007\no State Environmental Planning Policy (Koala Habitat Protection)\n2020\no State Environmental Planning Policy (Infrastructure) 2007\no State Environmental Planning Policy (Vegetation in Non-Rural\nAreas) 2017\no Gunnedah Local Environmental Plan 2012\n Draft environmental planning instruments: Nil\n Development control plans:\no Gunnedah Development Control Plan 2012\n Planning agreements: Nil\n Provisions of the Environmental Planning and Assessment Regulation\n2000: Nil\n Coastal zone management plan: Nil\n The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n The suitability of the site for the development\n Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":3},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n Council assessment report: 16 June 2021\n Written submissions during public exhibition: 26\n Verbal submissions at the public meeting:\no Allan and Donna Hanlen\no Renaye Benham\no Mac Howarth\no Robyn Howarth\no Council assessment officer - Wade Hudson\no On behalf of the applicant - Gary Peacock and Tim MacKellar","stage":"general","stage_basis":"heading","page":3},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n Briefing: 12 April 2021\no Panel members: Paul Mitchell (Chair), Penny Holloway, Stephen\nGow and Ann Luke\no Council assessment staff: Wade Hudson and Jack Morrissey\no Department: Sung Pak and Lisa Foley\n Applicant Briefing: 19 May 2021\no Panel members: Paul Mitchell (Chair) and Stephen Gow\no Applicant representatives: Gary Peacock, Tim MacKellar and\nBrendan MacKellar\no Council staff: Wade Hudson\no Department staff: Amanda Moylan and Lisa Foley\nNote: Applicant briefing was requested to provide the Panel with\nclarification and to respond to issues\n EPA Briefing: 17 June 2021\no Panel members: Paul Mitchell (Chair), Stephen Gow and Ann Luke\no EPA representative: Rebecca Scrivener\no Council staff: Wade Hudson\no Department staff: Carolyn Hunt and Lisa Foley\n Site inspection: 24 June 2021\no Panel members: Stephen Gow and Ann Luke\no Council assessment staff: Wade Hudson, Daniel Noble and\nAshleigh Stewart\no Department staff: Carolyn Hunt\n Final briefing to discuss council’s recommendation: 24 June 2021\no Panel members: Paul Mitchell (Chair), Penny Holloway, Stephen\nGow and Ann Luke\no Council assessment staff: Wade Hudson, Ashleigh Stewart, Daniel\nNoble and Jack Morrissey\no Department staff: Carolyn Hunt","stage":"general","stage_basis":"heading","page":3},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":4},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the council assessment report","text":"SCHEDULE 2 - Conditions of Consent\nA. THAT DEVELOPMENT CONSENT BE G RANTED SUBJECT TO THE FOLLOWING CONDITIONS:\nA1. The proposed development shall be carried out generally in accordance with the details set out in the\nfollowing:\n Development Application form lodged, 10 August 2020;\n Environmental Impact Statement, prepared by Outline Planning Co nsultants Pty Limited, dated\nJuly 2019;\n Response to Submissions: EIS Proposed Landfill Marys Mount Quarry, prepared by Outline\nPlanning Consultants Pty Limited, dated 8 October 2020;\n Response to Council RFI: EIS Proposed Landfill Marys Mount Quar ry, prepared by Outline\nPlanning Consultants Pty Limited, dated 15 January 2021;\n Response to Council’s Further Request for Additional Informatio n: Proposed Landfill in Quarry\nVoid at Marys Mount, prepared by Outline Planning Consultants Pty Limited, dated 21 May 2021;\nand\n Submitted plans:\n Prepared by Martens and Associates Pty Ltd, dated 20/05/2020, Project No. P1907436,\nPlanset No. PS01, Drawing No. PS01-A000, Rev C (Cover Sheet), D rawing No. P S0 1-B 20 0,\nRev B (Staging Plan), Drawing No. PS01-C102, Rev C (Stage 2 Lan dfill), Drawing No. PS01-\nC103, Rev C (Stage 3 Landfill),\n Prepared by Martens and Associates Pty Ltd, dated 14/05/2020, Project No. P1907436,\nDrawing No. PS01-A050, Rev B (Development Overview Plan), Drawing No. PS01-A100, Rev\nB (Pre-Quarry Surface), Drawing No. PS01-B100, Rev B (Cell Layout Plan), Drawing No. PS01-\nC100, Rev B (Final Rehabilitation Landform Final Stage), Drawing No. PS01-C500, Rev B\n(Finished Rehabilitation Volume Analysis Final Surface), Drawing No. PS01-C501, Rev B\n(Total Landfill Volume Analysis), Drawing No. PS01-C510, Rev A (Stage 1 Volume Analysis),\nDrawing No. PS01-C511, Rev A (Sta ge 2 Volume Analysis), Drawing No. PS01-C512, Rev A\n(Stage 3 Volume Analysis), Drawin g No. PS01-C600, Rev B (Final Rehabilitation Landform\nS e c t i o n S h e e t 1 ) , D r a w i n g N o . P S 0 1 - C 6 0 1 , R e v B ( F i n a l R e h a b i l i tation Landform Section\nSheet 2), Drawing No. PS01-C602 , Rev B (Final Rehabilitation La ndform Section Sheet 3),\nDrawing No. PS01-C603, Rev B (Final Rehabilitation Landform Section Sheet 4), Drawing No.\nPS01-C604, Rev B (Final Rehabilitation Landform Section Sheet 5), Drawing No. PS01-C605,\nRev B (Final Rehabilitation Landform Section Sheet 6), Drawing No. PS01-C606, Rev A (Stage","stage":"general","stage_basis":"heading","page":4},{"label":"1","code":null,"number":"1","title":"","text":"Section), Drawing No. PS01-C607, Rev A (Stage 2 Section), Drawing No. PS01-C608, Rev A\n(Stage 3 Section Sheet 1), Drawing No. PS01-C609, Rev A (Stage 3 Section Sheet 2),\n Prepared by Martens and Associates Pty Ltd, dated 22/05/2020, Project No. P1907436,\nDrawing No. PS01-C101, Rev D (S tage 1 Landfill), Drawing No. PS 01-E100, Rev D (Concept\nStormwater Management Plan), Dra wing No. PS01-E200, Rev A (Land fill Watercycle\nManagement Plan),\n Supporting Documentation:\n Landfill Design and Water Cycle M anagement Plan: Proposed Landf ill Facility, Marys Mount\nQuarry, Gunnedah, NSW, prepared by Martens and Associates Pty Ltd, dated June 2020, Ref:\nP1907436JR01V04;\n Traffic Impact Assessment, prepared by Street Wise Road Safety and Traffic Services, dated\n23/06/2020;\n Landfill Remediation Plan, prepared by Stringybark Ecological, dated July 2020, Document ID:\n200707_02, Revision 1;\n Air Quality Assessment, prepared by VIPAC Engineers and Scientists, dated 13 May 2021, Ref:\n70B-19-0119-TRP-10150359-2;\n Noise Impact Assessment Report, prepared by VIPAC Engineers and Scientists, dated 13 May\n2021, Ref: 70B-19-0119-TRP-10150359-2;\nexcept as otherwise provided by the conditions of consent.\nReason: To ensure compliance with application and plans.\nA2. To confirm and clarify the terms of this approval, consent is given for the following:\na) Disposal of no more than 200,000 tonnes per annum of non-putrescible waste to landfill;\nb) Disposal of no more than 2,509,000 cubic metres (approximately 4,014,000 tonnes) of non-\nputrescible waste to land fill over three (3) stages;\nc) Rehabilitation of the site (Stage 4).\nIf contrary to the maximum disposal volume of 2,509,000 cubic metres listed as b), the final land form\nis not to exceed that of the Fin al Rehabilitation Landform Final Surface Plan, prepared by Martens &\nAssociates Pty Ltd, dated 14/05/2020, Project No. P1907436, Drawing No. PS01-C100, Rev B.\nNote: Non-putrescible waste is wastes as permitted by condition A3.\nReason: To ensure compliance with application and plans.\nA3. To confirm and clarify the terms of this approval, development consent is given for the disposal of the\nfollowing wastes only:\n General Solid Wastes, including:\n Building and demolition waste other than from chemical works, m ineral processing works,\ncontainer reconditioning works or (human) waste treatment facilities;\n Asphalt waste (including asphalt resulting from road construction and water proofing works);\n Garden waste;\n Glass, plastic, rubber, plasterboard, ceramics, bricks, concrete or metal;\n Paper or cardboard;\n Household waste from municipal clean-up that does not contain food waste;\n Waste collected by, or on behalf of, local council’s from street sweepings;\n Grit, sediment, litter and gro ss pollutants collected in, and r emoved from, stormwater\ntreatment devices and/or stormwater management systems, that has been dewatered so\nthat they do not contain free liquids;\n G r i t a n d s c r e e n i n g s f r o m p o t a b l e w a t e r a n d w a t e r r e t i c u l a t i o n plants that has been\ndewatered so that it does not contain free liquids;\n Wood waste;\n Waste contaminated with lead (including lead paint waste) from residential premises or\neducation or child care institutions;\n Containers, previously containing dangerous goods, from which residues have been removed\nby washing or vacuuming;\n Drained oil filters (mechanically crushed), rags and oil-absorbent materials that only contain\nnon-volatile petroleum hydrocarbons and do not contain free liquids;\n Drained motor oil containers that do not contain free liquids;\n Non-putrescible vegetative waste from agriculture, silviculture or horticulture;\n Building cavity dust waste removed from residential premises or e d u c a t i o n a l o r c h i l d c a r e\ninstitutions, being waste that is packaged securely to prevent dust emissions and direct\ncontact;\n Synthetic fibre waste (from materials such as fibreglass, polye sters and other plastics) being\nwaste that is packaged securely to prevent dust emissions, but excluding asbestos waste;\n Biosolids categorised as unrestricted use, or restricted use, 1 , 2 or 3, in accordance with the\ncriteria set out in the Biosolids Guidelines;\n Cured concrete waste from batch plant;\n Fully cured and set thermosetting polymers and fibre-reinforcing resins;\n Fully cured dried residues of resins, glues, paints, coatings and inks;\n Excavated natural material (ENM), certified in accordance with Protection of Environment\nOperations (Waste) Regulations 2014;\n Virgin excavated natural material (VVENM);\n Materials subject to a Resource Recovery Order under Clause 91 and 92 of the Protection of\nEnvironment Operations (Waste) Regulations 2014, including recovered fines and treated drilling\nmud.\nDespite the wastes approved for disposal to landfill listed abo ve, this consent does not to permit the\ndisposal of any of the following wastes:\n Special waste (including clinical waste, asbestos-contaminated Construction & Demolition or\nCommercial & Industrial waste) but excluding sealed asbestos or waste tyres;\n Anything classified as special waste under an EPA gazettal notice as defined in EPA (2014a) Step 1;\n Liquid waste as defined in EPA (2014a) Step 2 eg. solvents, oils and greases;\n Waste pre-classified as hazardous waste as defined in EPA (2014 a ) S t e p 3 e g p a i n t s , d y e s ,\npesticides;\n General solid waste (putrescible) as defined in EPA (2014a) Step 4;\n Waste that requires chemical assessment to determine its classification as defined in EPA (2014a)\nStep 5.\nReason: To ensure compliance with application and plans.\nA4. To confirm and clarify the terms of this approval, development consent is given for the operational life\nof the Waste Disposal Facility for:\na) A maximum of 25 years from the commencement of the operation of the Waste Disposal Facility;\nOR\nb) The final landform identified on Final Rehabilitation Landform Final Surface Plan, prepared by\nMartens & Associates Pty Ltd, dated 14/05/2020, Project No. P19 07436, Drawing No. PS01-C100,\nRev B, is achieved;\nWhichever occurs first.\nUpon completion of the operational life, achieved by either a) or b) above, the developer is to cease\nall waste disposal. Within a minimum period of 6 months from the ceasing of waste disposal the\ndeveloper is to commence rehabilitation works as required by Stage 4 of the development proposal.\nNote. The Waste Disposal Facility (landfill) operator is requi red to inform Council of the\ncommencement date of waste disposal approved under this consent. Council will then provide written\nconfirmation of the lapsing date for landfill operations under this development consent.\nReason: To ensure a clear end of operational life and commence ment of rehabilitation work.\nA5. If there is any inconsistency between the documents referred to i n c o n d i t i o n A 1 , t h e m o s t r e c e n t\ndocument shall prevail to the extent of the inconsistency. Howev e r , t h e c o n d i t i o n s o f t h i s c o n s e n t\nshall prevail to the extent of any inconsistency.\nReason: To ensure compliance with application and plans.\nA6. T o c o n f i r m a n d c l a r i f y t h e t e r m s o f t h i s a p p r o v a l , a n y n o n - a u t horised or suspect wastes identified\nwithin vehicle loads are to be immediately removed of from site, until validated to be of a waste type\nlisted within condition A3. No non-authorised waste is to be stored within the boundaries of the\ndevelopment allotment.\nReason: To ensure compliance with application and plans.\nA7. T o c o n f i r m a n d c l a r i f y t h e t e r m s o f t h i s a p p r o v a l , n o v e h i c l e movements are permitted to or from\nPownall Road. All vehicle moveme nts to and from the site shall be via the right of carriageway over\nLot 2 DP 865898, 259 Barker Road from Marys Mount Road.\nReason: To ensure clarity of safety of vehicle movements, as safety of Pownall Road and Oxley\nHighway has not been considered as part of this development assessment.\nA8. The development consent is to be operated in such a manner as t o be consistent with the Koala Plan\nof Management, prepared by Niche Environment and Heritage, date d 9 July 2014, Project No. 1466,\nRev 3.\nReason: To ensure compliance with individual Koala Plan of Ma nagement approved for the site.\nA9. To confirm and clarify the terms of this approval and despite condition A3, loads of waste disposed to\nthe facility are not to contain a volume of any more than 20% of any such load as green waste. Green\nWaste is to be determined as per the waste classification withi n the NSW EPA Waste Classification\nGuidelines.\nReason: To ensure compliance with application and plans.\nB. PRESCRIBED CONDITIONS\nNote: The following conditions are prescribed conditions and ma y o r m a y n o t r e l a t e d i r e c t l y t o t h i s\ndevelopment.\nB1. Compliance with Building Code of Australia and insurance r equirements under the Home Building\nAct 1989\n(cf clauses 78 and 78A of EP&A Regulation 1994)\n(1) For the purposes of secti on 4.17(11) of the Act, the fo llowing conditions are prescribed in\nrelation to a development consent for development that involves any building work-\n( a ) t h a t t h e w o r k m u s t b e c a r r i e d o u t i n a c c o r d a n c e w i t h t he requirements of\nthe Building Code of Australia,\n( b ) i n t h e c a s e o f r e s i d e n t i a l b u i l d i n g w o r k f o r w h i c h t h e Home Building Act\n1989 requires there to be a contract of insurance in force in accor dance with Part 6\no f t h a t A c t , t h a t s u c h a c o n t r a c t o f i n s u r a n c e i s i n f o r c e b e f ore any building work\nauthorised to be carried out by the consent commences.\n(1A) For the purposes of section 4.17(11) of the Act, it is prescribed as a condition of a\ndevelopment consent for a temporary structure that is used as an entertainment venue, that\nthe temporary structure must comply with Part B1 and NSW Part H 102 of Volume One of\nthe Building Code of Australia.\n(2) This clause does not apply-\n( a ) t o t h e e x t e n t t o w h i c h a n e x e m p t i o n i s i n f o r c e u n d e r clause 164B, 187 or 188,\nsubject to the terms of any condition or requirement referred t o in clause 164B(4),\n187(6) or 188(4), or\n( b ) t o t h e e r e c t i o n o f a t e m p o r a r y b u i l d i n g , o t h e r t h a n a temporary structure to which\nsubclause (1A) applies.\n(3) In this clause, a reference to the Building Code of Australia is a reference to that Code as in\nforce on the date the application is made for the relevant-\n( a ) d e v e l o p m e n t c o n s e n t , i n t h e c a s e o f a t e m p o r a r y s t r u c ture that is an entertainment\nvenue, or\n( b ) c o n s t r u c t i o n c e r t i f i c a t e , i n e v e r y o t h e r c a s e .\nN o t e . There are no relevant provisions in the Building Code of Australia in respect of temporary\nstructures that are not entertainment venues.\nReason: To ensure compliance with the statutory requirements.\nB 2 . Erection of signs\n(1) For the purposes of section 4.17(11) of the Act, the re quirements of subclauses (2) and (3)\nare prescribed as conditions of a development consent for development that involves any\nbuilding work, subdivision work or demolition work.\n(2) A sign must be erected in a prominent position on any s ite on which building work, subdivision\nwork or demolition work is being carried out-\n( a ) s h o w i n g t h e n a m e , a d d r e s s a n d t e l e p h o n e n u m b e r o f t h e principal certifier for the\nwork, and\n( b ) s h o w i n g t h e n a m e o f t h e p r i n c i p a l c o n t r a c t o r ( i f a n y ) for any building work and a\ntelephone number on which that person may be contacted outside working hours,\nand\n( c ) s t a t i n g t h a t u n a u t h o r i s e d e n t r y t o t h e w o r k s i t e i s p rohibited.\n(3) Any such sign is to be maintained while the building wo rk, subdivision work or demolition\nwork is being carried out, but must be removed when the work has been completed.\n(4) This clause does not appl y in relation to building work , subdivision work or demolition work\nthat is carried out inside an ex isting building that does not a ffect the external walls of the\nbuilding.\n(5) This clause does not appl y in relation to Crown buildin g work that is certified, in accordance\nwith section 6.28 of the Act, to comply with the technical prov isions of the State’s building\nlaws.\n(6) This clause applies to a d evelopment consent granted before 1 July 2004 only if the building\nwork, subdivision work or demolition work involved had not been commenced by that date.\nNote. Principal certifiers and principal contractors must als o ensure that signs required by this\nc l a u s e a r e e r e c t e d a n d m a i n t a i n e d ( s e e c l a u s e 2 2 7 A w h i c h c u r r e ntly imposes a maximum\npenalty of $1,100).\nReason: To ensure compliance with the statutory requirements.\nB 3 . Notification of Home Building Act 1989 requirements\n(1) For the purposes of section 4.17(11) of the Act, the re quirements of this clause are prescribed\nas conditions of a development consent for development that inv olves any residential\nbuilding work within the meaning of the Home Building Act 1989.\n(2) Residential building work within the meaning of the Home Building Act 1989 must not be\ncarried out unless the principal certifier for the development to which the work relates (not\nbeing the council) has given the council written notice of the following information-\n(a) in the case of work for wh ich a principal contractor is required to be appointed-\n( i ) t h e n a m e a n d l i c e n c e n u m b e r o f t h e p r i n c i p a l c o n t r a c t or, and\n(ii) the name of the insur er by which the work is insured under Part 6 of that\nAct,\n( b ) i n t h e c a s e o f w o r k t o b e d o n e b y a n o w n e r - b u i l d e r -\n( i ) t h e n a m e o f t h e o w n e r - b u i l d e r , a n d\n( i i ) i f t h e o w n e r - b u i l d e r i s r e q u i r e d t o h o l d a n o w n e r - b u ilder permit under that\nAct, the number of the owner-builder permit.\n( 3 ) I f a r r a n g e m e n t s f o r d o i n g t h e r e s i d e n t i a l b u i l d i n g w o r k are changed while the work is in\nprogress so that the information notified under subclause (2) b ecomes out of date, further\nwork must not be carried out unless the principal certifier for the development to which the\nwork relates (not being the council) has given the council written notice of the updated\ninformation.\n(4) This clause does not apply in relation to Crown building work that is certified, in accordance\nwith section 6.28 of the Act, to comply with the technical prov isions of the State’s building\nlaws.\nReason: To ensure compliance with the statutory requirements.\nB 4 . Conditions relating to entertainment venues\nFor the purposes of section 4.17(11) of the Act, the requirements set out in Schedule 3A are prescribed\nas conditions of development consent for the use of a building as an entertainment venue.\nReason: To ensure compliance with the statutory requirements.\nB5. Fulfilment of BASIX Commitments\n(1) This clause applies to t he following development:\n(a) BASIX affected development,\n(b) any BASIX optional development in relation to which a perso n has made a\ndevelopment application that has been accompanied by a BASIX certificate or BASIX\ncertificates (despite there being no obligation under clause 2A of Schedule 1 for it to\nbe so accompanied).\n(2) For the purposes of section 4.17 (11) of the Act, fulfilme nt of the commitments listed in each\nr e l e v a n t B A S I X c e r t i f i c a t e f o r d e v e l o p m e n t t o w h i c h t h i s c l a u s e applies is a prescribed\ncondition of any development consent for the development.\nReason: To ensure compliance with the statutory requirements.\nB 6 . Condition relating to maximum capacity signage\n(1) For the purposes of section 4.17(11) of the Act, the re quirement set out in subclause (2) is\nprescribed as a condition of dev elopment consent (including an existing development\nconsent) for the following uses of a building, if the development consent for the use contains\na condition specifying the maximum number of persons permitted in the building-\n( a ) e n t e r t a i n m e n t v e n u e ,\n( b ) f u n c t i o n c e n t r e ,\n( c ) p u b ,\n( d ) r e g i s t e r e d c l u b ,\n( e ) r e s t a u r a n t .\n(2) From 26 January 2010, a sign must be displayed in a pro minent position in the building stating\nthe maximum number of persons, as specified in the development consent, that are\npermitted in the building.\n(3) Words and expressions use d in this clause have the same meanings as they have in the\nStandard Instrument.\nReason: To ensure compliance with the statutory requirements.\nB 7 . Condition relating to shoring and adequacy of adjoining property\n(1) For the purposes of section 4.17(11) of the Act, it is a prescribed condition of development\nconsent that if the development involves an excavation that ext ends below the level of the\nbase of the footings of a building, structure or work (including any structure or work within a\nroad or rail corridor) on adjoin ing land, the pe rson having the benefit of the development\nconsent must, at the person’s own expense-\n( a ) p r o t e c t a n d s u p p o r t t h e b u i l d i n g , s t r u c t u r e o r w o r k f rom possible damage from the\nexcavation, and\n(b) where necessary, underpin the building, structure or w ork to prevent any such\ndamage.\n(2) The condition referred to in subclause (1) does not app ly if the person having the benefit of\nthe development consent owns the adjoining land or the owner of the adjoining land has\ngiven consent in writing to that condition not applying.\nReason: To ensure compliance with the statutory requirements.\nC. PRIOR TO COMMENCEMENT OF WORKS\nC1. Prior to work commencing and for the life of the development, the developer must install and maintain\nsuitable erosion and sediment control measures onsite, in accordance with the relevant requirements\nof the Managing Urban Stormwater: Soils and Construction - Volume 1: Blue Book (Landcom, 2004).\nReason: To ensure erosion and sediment control on the development site.\nC2. Prior to work commencing the applicant is to prepare a Landfil l Environmental Management Plan\n(LEMP) to the satisfaction of Gunnedah Shire Council.\nAs part of the LEMP, the applicant must include the following:\n(a) describe the role, respon sibility, authority and accountability of all key personnel involved in the\nenvironmental management of the landfill development, including the keeping of records and\nmonitoring results;\n(b) describe the procedures that would be implemented to:\n(i) keep the local community and relevant agencies informed ab out the operation and\nenvironmental performance of the development;\n(ii) receive, handle, respond to, and record complaints;\n(iii) resolve any dis putes that may arise;\n(iv) respond to any incidents;\n(v) respond to emergencies. In this regard the LEMP shall also include an emergency response\nplan, prepared by the applicant, which shall document the procedures to deal with all types\nof incidents (eg: breakdowns of equipment and plant) that may o ccur at the premises that\nare likely to cause harm to the environment; and\n(c) include the following management plans:\n(i) Landfilling and Leachate Man agement Plan, including measur es to control landfill\noperations, the acceptance and handling of waste, and leachate management measures as\nidentified in the documents referred to in Condition A1 of the consent;\n(ii) Site Water and Groundwater Management Plan including measures to control ground water\nand surface water impacts as identified in the documents referred to in Condition A1 of the\nconsent;\n(iii) Air Quality Management Pla n, including measures to control dust and odours as identified\nin the documents referred to in Condition A1 of the consent;\n(iv) Noise Management Plan, including measures to control noise as identified in the documents\nreferred to in Condition A1 of the consent;\n(iv) Landfill Closure and Rehabilitation Plan (LGMP) developed i n a c c o r d a n c e w i t h t h e\nrequirements of the EPA's Environmental Guidelines: Solid Waste Landfills 2016 or its latest\nversion, and including measures as identified in the documents referred to in Condition A1\nof the consent;\n(v) Vegetation Management Plan, including measures as identifi ed in the documents referred\nto in Condition A1 of the consent;\n(vi) Landfill Day Management Pla n; including measures relating to site security, WH&S\nmanagement system, traffic management, driver code of conduct, measures to minimise\nkoala injury and death, litter an d debris control, fire managem ent, pollution incidents and\nemergencies (including contact details for emergency services), and the control of feral\npests and vermin, as identified in the documents referred to in Condition A1 of the consent;\n(vii) Koala Management Plan, including measures as identified in the currently approved Koala\nPlan of management as well as measures as identified in the documents referred to in\nCondition A1 of the consent;\n(viii) Pollution Incident Management; and\n(ix) Bushfire Management Plan.\n(d) Include the following:\n(i) Contact telephone number de tails: Within 3 months of the date of issue of the revised EPL,\nthe applicant must operate during its operating hours a telepho ne complaints line for the\npurpose of receiving any complaints from members of the public in relation to activities\nconducted at the Premises or by the vehicle or mobile plant, un less otherwise specified in\nthe EPL;\n(ii) Complaints register: The ap plicant must keep a legible record of all complaints made to the\napplicant or any employee or agent of the applicant in relation to pollution arising from any\nactivity to which this Consent applies. This record must include details of the following:\n The date and time of the complaint;\n The method by which the complaint was made;\n Any personal details of the complainant which were provided by the complainant or,\nif no such details were provided, a note to that effect;\n The nature of the complaint; The action taken by the Applicant i n r e l a t i o n t o t h e\ncomplaint, including any follow-up contact with the complainant; and\n If no action was taken by the Applicant, the reasons why no action was taken.\n(iii) Community notification an d liaison: The local community, and in particular the owners the\nnearby residences, shall be kept informed of the progress of the landfill operation over time.\nExcept in the case of an emergency, notification shall occur at least 24 hours prior to the\nworks being undertaken.\ne) Include the following:\n(i) Site Security;\n(ii) OH&S Management System; and\n(iii) Contact details fo r emergency services;\nNote: any existing plan in effect for the site relating to the existing Extractive Industry may be updated\nto include reference to the Waste Disposal Facility and the terms of this consent.\nReason: To ensure that appropriate Management Plans are developed for the ongoing operation of\nthe Waste Management Facility.\nIdentification of Waste Disposal Boundary\nC3. Prior to the commencement of operations of each stage of the W aste Management Facility, a \"Peg\nSurvey Report\", including clear physical markers (durable pegs), is to be supplied to Council confirming\nthe location of the external boundary of the land fill area for the stage. Waste disposal is only\npermitted within the area identified by the physical markers.\nReason: To ensure that waste is only deposited within the approved waste disposal area.\nC4. Financial Assurance - POEO Act 1997.\nIn accordance with Part 9.4 of the Protection of the Environment Operations Act 1997 , prior to the\ncommencement of any works or disposal of any material, whicheve r occurs first, the operator of the\nWaste Disposal Facility is to pro vide ‘Financial Assurance’ as to the cost of all rehabilitation works to\nthe NSW Environment Protection A uthority (NSW EPA). The Financi al Assurance is to be provided in\nthe form of an unconditional and irrevocable guarantee from an Australian bank, building society or\ncredit union in favour of the NSW Environment Protection Author ity. The requirement for Financial\nAssurance is to be included within the Environmental Protection Licence.\nThe value of Financial Assurance is to be determined by the appropriate regulatory authority and is to\nbe to the amount which represents a reasonable estimate of the total likely costs and expenses that\nmay be incurred in carrying out any remediation and/or rehabili t a t i o n w o r k s r e q u i r e d b y t h e\ndevelopment. In determining this reasonable estimate the developer is to engage an independent\nexpert to prepared advice as to the total cost of rehabilitation and/or remediation works. The Financial\nAssurance shall be adjusted each financial year in line with the Consumer Price Index (CPI) for the\nprevious year.\nThe EPA may require an increase in the amount of the financial assurance at any time as a result of\nreassessment of the total likely costs and expenses of rehabilitation of the premises.\nThe Financial Assurance must contain a term that provides that any money claimed can be paid to the\nNSW EPA or, at the written direction of the NSW EPA, to any person. The Financial Assurance must be\nmaintained during the operation of the facility and thereafter u n t i l s u c h t i m e a s t h e N S W E P A i s\nsatisfied the premises is environmentally secure and any required remediation work are completed.\nThe financial assurance must be replenished by the full amount claimed or realised if the NSW EPA has\nclaimed on or realised the financial assurance or any part of it to undertake a work or program required\nto be carried out by the licence which has not been undertaken by the licence holder.\nThe licencee must provide to the EPA the original counterpart g uarantee within five working days of\nthe issue of the financial assurance required by this condition and the adjusted financial assurance as\nrequired by this condition.\nThe EPA may claim on a financial assurance under S303 of the PO EO Act if a licencee fails to carryout\nany work or program required to comply with the condition the Environmental Protection Licence\n(EPL).\nReason: To ensure at an appropriate Financial Assurance guarantee is provided to the cost of\nremediation work that is required because of activities underta ken as part of development works,\nbeing the works to which an Environmental Protection Licence wi ll be subject, in accordance with\nPart 9.4 of the Protection of the Environment Operations Act 1997.\nC5. Prior to the commencement of any operations the Developer shall pay to Council a levy as applicable at\nthe time of payment, relative to the total project value, in ac cordance with the Council’s Section 94A\nContributions Plan 2013 under Section 7.12 of the Environmental Planning and Assessment Act 1979.\nThe current levy payable is calculated at 1% of the development c o s t . T h e p a y m e n t o f S 7 . 1 2\ncontributions must be accompanied by a Quantity Surveyors Report, prepared by a Quantity Surveyor\nregistered with the Australian Institute of Quantity Surveyors, in accordance with 1.13 of the Gunnedah\nS94A contributions Plan.\nNote: The Gunnedah Shire Council ’s Section 94A Contributions Plan 2013 can be viewed on Council’s\nweb site at: http://www.gunnedah.nsw.gov.au\nReason: To make provision for public amenities and services within the community.\nE. GENERAL\nE1. The waste management facility is to be operated in accordance with NSW EPA Guidelines: Solid Waste\nLandfill, 2nd Edition (2016), or subsequent versions AND the Environmental P rotection Licence issued\nfor the facility, by the NSW Environmental Protection Authority, as amended from time to time.\nReason: To ensure appropriate operation of the facility in accordance with EPA Guidelines.\nE2. S t o r m w a t e r f r o m w i t h i n t h e w a s t e l a n d f i l l i s n o t t o b e d i r e c t ly discharged or concentrated onto\nadjoining land. Stormwater is to be managed in accordance with the Landfill Design and Water Cycle\nManagement Plan: Proposed Landfill Facility, Marys Mount Quarry, Gunnedah NSW, prepared by\nMartens Consulting Engineers, dated June 2020, Ref: P1907436JR01V04, except as elsewhere required\nby condition of consent.\nReason: To ensure compliance with Council’s requirements.\nE3. All Leachate and Stormwater generated/captured within the Waste Disposal Facility landfill area is to\nbe discharged to the Stormwater and Leachate Sump and/or Leachate Dam. Leachate or Stormwater\ngenerated/captured within the Waste Disposal Facility landfill area is not permitted to be discharged\nfrom the site or to a natural water course located within the s ite, expect where transported off the\npremises to a facility lawfully able to receive and treat or process the leachate.\nReason: To ensure potentially contaminated water are adequately managed and retained onsite to\nensure that not discharged from the site of these waters occurs.\nTraffic and Parking\nE4. Onsite car parking accommodation shall be provided for a minimu m of six (6) vehicles, to ensure the\nprovision of adequate on-site parking facilities commensurate with the demand likely to be generated\nby the proposed development. This parking number is in addition to any previous parking demand\nalready present onsite, and relates to the parking demand gener ated by the Waste Disposal Facility.\nThese parking spaces are to be provided in excess of any other onsite parking demand generated by\nany other development consent effective on the development site.\nReason: To ensure compliance with Council’s requirements.\nE5. All internal driveways, parking areas, loading bays and vehicul ar turning areas are to be constructed\nwith a base course of adequate depth to suit design traffic. Parking areas must comply with AS 2890 -\nParking Facilities.\nReason: To ensure compliance with relevant Australian Standards and to facilitate the use of\nvehicular access and parking facilities.\nHaulage\nE6. Haulage operations shall cease w hen the school bus is travellin g along the identified sections of the\nhaul route as illustrated on the submitted plan - Haulage Opera tions to Cease at School Bus Times,\nprepared by Stewart Surveys Pty Ltd, at the following times on school days:\n Marys Mount Road to Quia Road - 7.50am-8.10am and 3.50pm-4.10pm;\n Emerald Hill to Quia Road - 7.50am-8.10am and 3.50pm-4.10pm; and\n Quia Road to Gunnedah - 8.00am-8.30am and 3.30pm-4.00pm.\nNote: Should a school bus operating time or the bus route change, an amendment to the above time\nand/or route shall be submitted to and approved by Council prior to any change in haulage operations.\nReason: To ensure compliance with submitted documentation.\nE7. All haulage operations are to be limited to the following routes:\n Via Barker Road - Marys Mount Road - Goolhi Road - Kamilaroi Hi ghway (at Emerald Hill);\nand\n Via Barker Road - Marys Mount Road - Goolhi Road - Quia Road - Blackjack Road - Oxley\nHighway (west of Gunnedah).\nNo vehicle movements are to occur from the vehicle access to Pownall Road.\nA record of movements shall be kept, noting the direction, date, and type of haulage vehicle utilised.\nThe record of movements shall be submitted to Council every 12 months. The register shall also be\nmade available to Council upon request.\nNote: There shall be no haulage of material extracted from the development site on any other public\nroad, without an amendment to this development consent.\nReason: To ensure compliance with application and plans.\nE8. The haulage of material is only permitted to be undertaken in v ehicles legally permitted by the road\nauthority to be used within the road network of the haulage route identified in condition D3.\nReason: To ensure compliance with application and plans.\nOutdoor Lighting\nE9. Outdoor lighting is to comply with AS/NZS 11583.1 Pedestrian Area (Category P) Lighting and AS4282\nControl of Obtrusive Effects of Outdoor Light.\nReason: To ensure compliance.\nDocumentation\nE10. A copy of all the approved documents related to this consent, s hall be kept on site at all times and\nshall be made available upon inspection by Council or an authorised government agency.\nReason: To ensure all documents are available on inspection.\nE11. Until they are replaced by an eq uivalent strategy, plan or prog ram approved under this consent, the\nOperator shall continue to implement existing strategies, plans or programs for operations on site that\nhave been approved by previous consents or approvals.\nReason: To ensure existing plans, strategies or programs are implemented until updated reports are\nendorsed.\nE12. A copy of the Annual Return required in the General Terms of Approval shall be provided to Council in\naddition to the requirements of the Environment Protection Authority.\nReason: To ensure compliance with application and plans.\nE13. The Leachate Dam is to have a minimum capacity of 7ML. The Stor mwater and Leachate sump is to\nhave a minimum capacity of 3.5ML for Stage 1 and a minimum capa city of 4.5ML for Stages 2 and 3,\nunless otherwise approved and acknowledged in the Environmental Protection Licence issued for the\nfacility, by the NSW Environmental Protection Authority, as amended from time to time.\nReason: To ensure that leachate storage is provided to a minimum capacity in accordance with\nLandfill Design and Water Cycle Management Plan.\nE14. Dam ‘A’, as indicated on Concept Stormwater Management Plan, prepared by Martens and Associates\nPty Ltd, dated 22/05/2020, Project No. P1907436, Drawing No. PS01-E100, Rev D, is to have a\nminimum capacity of 7.7ML.\nReason: To ensure that Stormwater detention dams have adequate capacity in accordance with\nLandfill Design and Water Cycle Management Plan.\nE15. The Operator is to establish appropriate diversion banks and swales directing surface water away from\nthe waste disposal area within the landfill into stomrwater detention dams.\nReason: To ensure appropriate management of surface water.\nE16. No discharge is permitted from the development site from the Lea c h a t e D a m o r S t o r m w a t e r a n d\nLeachate Sump, identified on Lan dfill Watercycle Management Pla n, prepared by Martens and\nAssociates Pty Ltd, dated 22/05/2020, Project No. P1907436, Dra wing No. PS01-E200, Rev A, except\nwhere permitted by Condition O5.6 the General Terms of Approval issued by the Environmental\nProtection Authority included within Annexure B.\nReason: To ensure no leachate and possible suspended contaminates migrate from the site.\nE17. The Leachate Dam identified on Development Overview Plan, prepared by Martens and Associates Pty\nLtd, dated 14/05/2020, Project No. P1907436, Drawing No. PS01-A050, Rev B, is to be managed as to\nalways have a minimum capacity of 1.9ML as available for capture of runoff.\nReason: To ensure Leachate dams are maintained with a suitable capacity.\nE18. The Leachate Dam is to be regularly maintained and cleaned. Any sludge/silt removed from the\nLeachate Dam is to be disposed of into the approved Waste Disposal Facility area onsite, only. Material\nis not to be disposed elsewhere onsite.\nAny sludge/silt removed from th e Leachate Dam, is to be tested to ensure that it meets the\nclassification parameters as Solid Waste Non-Putrescible. In the event that the removed material does\nnot constitute Solid Waste Non-Putrescible the waste is to be r emoved from site and disposed to a\nsuitably licenced Waste Management Facility.\nReason: To ensure a suitable capacity is maintained within Leachate dams and removed material is\ndisposed to locations as indicated within the development appli cation and Environmental Impact\nStatement.\nE19. The Operator shall ensure that all plant and equipment used for the Development is maintained in a\nproper and efficient condition and operated in a proper and efficient manner.\nReason: To ensure appropriate management of machinery and equipment.\nE20. The Operator shall repair, or pay the full costs associated wit h the repair of any public infrastructure\nthat is damaged by the developer.\nReason: To ensure that the community is not responsible for the costs of repair of any damage to\npublic infrastructure.\nE21. The operator of the Waste Disposal Facility shall install and maintain a security fence and gates around\nthe perimeter of the waste disposal area (cell) for each stage of works. The operator is to ensure that\nthe security gates around the waste disposal area are locked whenever the site is unattended.\nReason: To ensure that suitable security fencing is installed a\nnd managed.\nComplaints Register\nE22. The operator of the Waste Dispos al Facility shall nominate a co ntact person and telephone number\nfor the benefit of adjoining nei ghbours and establish a complai nts register that in clu de s recor ds of\nnature, time and date of complaint, climatic conditions such as wind direction and speed and the\naction taken to address complaint. The register shall be made available to Council upon request.\nThe developer shall notify all landowners and tenants within a 5.0 kilometre distance of the boundary of\nt h e d e v e l o p m e n t s i t e i n w r i t i n g o f t h e c o n t a c t d e t a i l s a n d a s s ociated information and that they may\ncontact the quarry operator to make representations regarding the operation of the Waste Disposal\nFacility. A copy of the notification shall be provided to Council.\nReason: To ensure amenity of area.\nE23. The developer is to provide CCTV cameras, in sufficient number and location to provide adequate\ncoverage to the active waste disposal area. These cameras are to be in addition to any camera systems\nalready in operation within the site. The capacity of footage storage should be a minimum of 28 days\nw i t h t h e h a r d d r i v e / s s e c u r e d i n a s o l i d r e c e p t a c l e o r e x t e r n a l facility to avoid being removed by\noffender/s.\nCamera footage should be made a vailable to any public authority upon request.\nReason: To ensure adequate security measures and surveillance is provided due to the rural nature\nof the facility and absence of onsite occupation.\nE24. The operator of the Waste Disposal Facility must undertake suitable landscaping on private property,\nupon request from member of the public where it is determined that a residential receiver has visual\nimpact from the operation of the Waste Disposal Facility. The p osition and suitable extent of\nlandscaping is to be determined in consultation with the land owner and Gunnedah Shire Council.\nLandscaping plans and selected veg etation species should be sui table to act as a visual screen of the\nWaste Disposal Facility, when viewed from the affected receiver.\nI t i s t o t h e d i s c r e t i o n o f G u n n e d a h S h i r e C o u n c i l t o d e t e r m i n e if a request under this Condition is\nunreasonable, to determine if visual impact from the Waste Disp osal Facility warrants establishment\nof a landscaping barrier.\nNote: Visual impacts are to be as a consequence of the Waste D isposal Facility only, Landscaping is not\nto address visual impacts from the operation of the Extractive Industry (Quarry) or other activity which\nhas approval under a separate development consent.\nReason: To ensure that suitable landscaping is conducted at nea rby receivers if visual impacts are\ndetermined.\nF. DURING WORKS\nF1. A stamped copy of the development consent, the approved plans and specifications are to be kept at\nthe construction site at all times during the construction period.\nReason: To ensure compliance with approved application and plans.\nF2. The approved erosion and sediment control facilities are to be provided and maintained throughout\nthe construction and operation of the development.\nReason: To ensure compliance with Council’s requirements.\nF3. All operation works shall cease on site should the identificat ion of an item of potential Aboriginal or\nEuropean heritage significance be discovered during operation works. The Office of Environment and\nHeritage shall be contacted and any required approvals are to b e obtained before the re-\ncommencement of operation works.\nReason: To ensure that any item of heritage significance uncovered is suitably managed.\nF4. Toilet facilities\nToilet facilities are to be provided, at or in the vicinity of the work site on which work involved in the\nerection or demolition of a building is being carried out, at the rate of one toilet for every 20 persons\nor part of 20 persons employed at the site.\nEach toilet provided:\n(a) must be a standard flushing toilet, and\n(b) must be connected:\n(i) to a public sewer, or\n(ii) if connection to a public sew er is not practicable, to an accredited sewage management\nfacility approved by the Council, or\n(iii) if connection to a public s ewer or an accredited sewage management facility is not\npracticable, to some other sewage management facility approved by the Council.\nThe provision of toilet facilitie s in accordance with this clau se must be completed before any other\nwork is commenced. In this clause:\naccredited sewage management facility means a sewage management facility to which Division 4A of\nP a r t 3 o f t h e Local Government (Approvals) Regulation 1993 a p p l i e s , b e i n g a s e w a g e m a n a g e m e n t\nfacility that is installed or con structed to a design or plan t he subject of a certif icate of accreditation\nreferred to in clause 95B of the Regulation.\napproved by the Council means the subject of an approval in force under Division 1 of Par 3 of the\nLocal Government (Approvals) Regulation 1993.\npublic sewer has the same meaning as it has in the Local Government (Approvals) Regulation 1993.\nsewage management facility h a s t h e s a m e m e a n i n g a s i t h a s i n t h e Local Government (Approvals)\nRegulation 1993.\nReason: To ensure environmental health standards are met.\nServices Provision\nF5. A Restriction as to User, pursuant to Section 88B of the Conveyancing Act 1919 , is to be submitted\nwhich provides for the creation of an easement, in favour of Gunnedah Shire Council over the following\nlocations:\na) The entire waste disposal/landfill area (Stages 1, 2 and 3);\nb) The Leachate Dam;\nThe restriction as to user is to prohibit any construction or excavation from occurring within the\nidentified area, to protect cell integrity by preventing penetration of final cell lining structure.\nReason: To ensure that appropriate easements are created over all waste disposal locations and any\nother potential location of contamination.\nG. CONTINUED OPERATIONS\nOperation Hours\nG1. The landfill operation hours are limited to the following:\n Monday to Friday - 7.00am to 6.00pm (Australian Eastern Daylight Time)\n Monday to Friday - 7.00am to 5.00pm (Australian Eastern Standard Time)\n Saturday - 8.00am to 3.00pm\n Sunday and Public Holidays - closed.\nReason: To ensure compliance with application and plans.\nG2. The sealing to all internal driveways, vehicular parking, mano euvring and loading areas is to be\nmaintained at all times.\nReason: To ensure maintenance of car parking areas.\nG3. All vehicular movement to and from the site shall be in a forw ard direction to ensure that the proposed\ndevelopment does not give rise to vehicle reversing movements on o r o f f t h e P u b l i c R o a d w i t h\nconsequent traffic accident potential and reduction in road efficiency.\nReason: To ensure compliance with Council’s requirements.\nG4. Any waste unable to accepted f or disposal onsite is to be rem oved and be disposed of to a suitably\nlicenced waste management facility.\nReason: To ensure unauthorised waste is disposed of off-site in an appropriate manner.\nG5. The Operator shall ensure that the operation of the development is undertaken in accordance with all\nrelevant updated and/or amended strategies, management plans and programs approved by the\nGunnedah Shire Council as part of the conditions of this consent.\nReason: To ensure compliance with Council’s requirements.\nG6. Operations of the Waste Disposal Facility is to be limited to a maximum of 60 truck movements\n(includes loaded and unloaded) per day.\nReason: To ensure compliance with application and plans.\nG7. All works shall cease on site sh ould the identification of an item of potential Aboriginal or European\nheritage significance be discovered during excavation and operational works. The NSW Environment,\nEnergy and Science shall be contacted and any required approval s are to be obtained before the re-\ncommencement of excavation and operational works.\nReason: To ensure that any item of heritage significance uncovered is suitably managed.\nAir Quality Mitigation\nG8. To minimise the potential for dust nuisance generated by the de velopment, the mitigation measures\noutlined in Section 6.2.1 Particu l a t e M a t t e r , T a b l e 2 . 2 , o f t h e Air Quality Assessment, prepared by\nVIPAC, dated 13 May 2021, ref: 70B-19-0119-TRP-10150359-2, shall be implemented during the\noperations of the development.\nReason: To ensure compliance with application and plans.\nNoise Mitigation Measures\nG9. To ensure compliance with the NSW Noise Policy for Industry (2017) the mitigation measures outlined\nin Section 9 Operating Mitigation Recommendations, of the Envir onmental Noise Assessment,\nprepared by VIPAC, dated 21 May 2021, ref: 20E-19-0293-TRP-10550042-3, shall be implemented\nduring the operations of the development.\nReason: To ensure compliance with application and plans.\nH. General Terms of Approval - E nvironment Protection Authority\nH1. The development shall be carried out in accordance with the Ge neral Terms of Approval issued by the\nEnvironmental Protection Authority, attached in Annexure B to this consent.\nReason: To ensure compliance with statutory requirements.","stage":"general","stage_basis":"heading","page":5}]});
